"""Generate the homepage, portfolio catalog and project pages from approved content."""
from pathlib import Path
from html import escape as e
import json,re
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'dist'
projects=json.loads((ROOT/'content/projects.json').read_text())
home=(ROOT/'src/home.html').read_text().replace('<sup>03</sup>',f'<sup>{len(projects):02d}</sup>')
def preview(p,case=False):
 s=p['slug']
 return f'''<div class="project-visual" data-preview="{s}"><span class="project-category">{e(p['sector'].upper())}</span>{'<span class="cenia-decoration" aria-hidden="true">Crecer<br>juntos.</span>' if s=='cenia' and not case else ''}<div class="preview-window"><span class="window-bar"><i></i><i></i><i></i><span>{s} / web</span><span class="live-indicator" hidden>EN VIVO</span></span><div class="preview-screen"><img src="/assets/{p['image']}" alt="{e(p['alt'])}" width="1280" height="720" loading="lazy"><div class="live-stage" aria-hidden="true" inert></div></div></div><button type="button" class="preview-play" data-preview-url="{e(p['url'])}" aria-pressed="false" aria-label="Reproducir vista de {e(p['name'])}"><span class="play-icon" aria-hidden="true"></span><span class="play-label">Ver en movimiento</span></button><span class="preview-status" role="status"></span></div>'''
def card(p):
 return f'''<article class="project-card project-{p['slug']} reveal" data-sector="{e(p['sector'])}" data-search="{e((p['name']+' '+p['sector']+' '+p['kind']).lower())}">{preview(p)}<div class="project-meta"><div><h3><a href="/proyectos/{p['slug']}/">{e(p['name'])}</a></h3><p>{e(p['tagline'])}</p></div><a class="case-link" href="/proyectos/{p['slug']}/">Ver proyecto <span aria-hidden="true">+</span></a></div><p class="project-type">{e(p['kind'])} · {e(p['city'])}</p></article>'''
featured=[p for p in projects if p.get('featured',True)][:3]
feature='<div class="project-grid">'+''.join(card(p) for p in featured)+'</div>'
(OUT/'index.html').write_text(home.replace('{{FEATURED_PROJECTS}}',feature))
header=re.search(r'  <header.*?</header>',home,re.S).group().replace('href="#inicio"','href="/"').replace('href="#servicios"','href="/#servicios"').replace('href="#nosotros"','href="/#nosotros"').replace('href="#contacto"','href="/#contacto"')
footer=re.search(r'  <footer.*?</footer>',home,re.S).group().replace('href="#inicio"','href="#top"').replace('href="#top" class="wordmark"','href="/" class="wordmark"')
def page(title,description,body,pageclass):
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f2f0e9"><meta name="robots" content="noindex,nofollow"><title>{e(title)} — Colab</title><meta name="description" content="{e(description)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><script src="/contact-config.js" defer></script><script src="/app.js" defer></script></head><body class="{pageclass}" id="top"><a class="skip-link" href="#contenido">Ir al contenido</a>{header}<main id="contenido">{body}</main>{footer}</body></html>'''
cta='''<section class="project-cta section-wrap reveal"><div><p class="eyebrow">EL SIGUIENTE PODRÍA SER EL TUYO</p><h2>Una web que se sienta<br>como <em>tu marca.</em></h2></div><a href="/#contacto" class="pill black">Hablemos de tu proyecto <span class="button-symbol" aria-hidden="true"><span class="chat-symbol"></span></span></a></section>'''
filters=''.join(f'<button type="button" class="filter" data-filter="{e(s)}" aria-pressed="false">{e(s)}</button>' for s in dict.fromkeys(p['sector'] for p in projects))
body=f'''<section class="catalog-intro section-wrap"><p class="eyebrow">EL PORTAFOLIO / COLAB</p><h1>Distintas marcas.<br>La misma <em>curiosidad.</em></h1><div class="catalog-lead"><p>Restaurantes, servicios y espacios para aprender.<br>Explora las webs y las ideas que les dieron forma.</p><span class="project-count">{len(projects):02d}<small>PROYECTOS</small></span></div></section><section class="catalog section-wrap" aria-label="Catálogo de proyectos"><div class="catalog-tools"><div class="filters" role="group" aria-label="Filtrar por sector"><button type="button" class="filter" data-filter="all" aria-pressed="true">Todos</button>{filters}</div><label class="search-label"><span>Buscar un proyecto</span><input type="search" id="project-search" placeholder="Nombre o sector…" autocomplete="off"></label></div><p id="catalog-count" class="catalog-count" aria-live="polite">{len(projects)} proyectos</p><div class="project-grid catalog-grid">{''.join(card(p) for p in projects)}</div><p id="catalog-empty" hidden>No encontramos proyectos con esa búsqueda. Prueba otro nombre o sector.</p><nav id="pagination" class="pagination" aria-label="Páginas del portafolio" hidden></nav></section>{cta}'''
(OUT/'proyectos').mkdir(exist_ok=True)
(OUT/'proyectos/index.html').write_text(page('Proyectos','Explora los sitios web de Ajitate, Lockpoint y CENIA: diseño, desarrollo y rediseño por Colab.',body,'catalog-page'))
for i,p in enumerate(projects):
 nxt=projects[(i+1)%len(projects)]
 features=''.join(f'<article class="reveal"><span class="feature-number">0{j+1}</span><h3>{e(t)}</h3><p>{e(d)}</p></article>' for j,(t,d) in enumerate(p['features']))
 body=f'''<section class="case-hero section-wrap"><a href="/proyectos/" class="breadcrumb">Portafolio / {e(p['name'])}</a><div class="case-title"><h1>{e(p['name'])}<span class="logo-dot">.</span></h1><p>{e(p['tagline'])}</p></div><div class="case-facts"><span><small>SECTOR</small>{e(p['sector'])}</span><span><small>TRABAJO</small>{e(p['kind'])}</span><span><small>UBICACIÓN</small>{e(p['city'])}, Ecuador</span><a class="pill black" href="{e(p['url'])}" target="_blank" rel="noopener noreferrer">Visitar sitio <span class="button-symbol" aria-hidden="true">◎</span></a></div><div class="case-preview project-{p['slug']}">{preview(p,True)}</div><p class="preview-caption">El sitio real, en movimiento. Activa la vista o abre el sitio para recorrerlo.</p></section><section class="case-story section-wrap"><div class="reveal"><p class="eyebrow">UNA PRESENCIA CON INTENCIÓN</p><h2>{e(p['tagline'])}</h2></div><div class="reveal"><p>{e(p['description'])}</p><p>{e(p['intent'])}</p></div></section><section class="case-features section-wrap" aria-label="Dentro del proyecto">{features}</section><section class="case-next section-wrap reveal"><div><p class="eyebrow">SIGUE EXPLORANDO</p><h2>{e(nxt['name'])}</h2></div><a href="/proyectos/{nxt['slug']}/" class="pill outline">Conoce el proyecto <span class="button-symbol" aria-hidden="true">+</span></a></section>{cta}'''
 dest=OUT/'proyectos'/p['slug']; dest.mkdir(exist_ok=True)
 (dest/'index.html').write_text(page(p['name'],p['description'],body,'case-page'))
print(f'Generated homepage, portfolio and {len(projects)} project pages.')
